import{_ as t,a,c as n,ac as r}from"./chunks/framework.BSuaGltH.js";const p=JSON.parse('{"title":"第一册：英语初阶 · Lesson 19 Tired and thirsty","description":"学习 主格和宾格，配有原创例句、重点词汇和带解析的自测。","frontmatter":{"title":"第一册：英语初阶 · Lesson 19 Tired and thirsty","description":"学习 主格和宾格，配有原创例句、重点词汇和带解析的自测。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"路线与能力起点","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"新概念英语经典版第1册课时","summary":"学习 主格和宾格，配有原创例句、重点词汇和带解析的自测。","status":"active","related":[{"title":"程序员英语 08：一次完整的阅读与协作实战","link":"/life/english/programmer/practice","kind":"读写与对话练习","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语","link":"/life/english/new-concept/book-2/unit-01/vocabulary","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 第17–24课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-02","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 字母索引与第1–16课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-01","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 复习与自测","link":"/life/english/new-concept/book-2/unit-01/review","kind":"读写与对话练习","scope":"general","audience":"general"}],"prev":{"text":"第一册：英语初阶 · Lesson 18 What are their jobs?","link":"/life/english/new-concept/book-1/unit-01/lesson-018"},"next":{"text":"第一册：英语初阶 · Lesson 20 Look at them!","link":"/life/english/new-concept/book-1/unit-01/lesson-020"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第一册：英语初阶 · Lesson 18 What are their jobs?","link":"/life/english/new-concept/book-1/unit-01/lesson-018"},"next":{"text":"第一册：英语初阶 · Lesson 20 Look at them!","link":"/life/english/new-concept/book-1/unit-01/lesson-020"}},"headers":[],"relativePath":"life/english/new-concept/book-1/unit-01/lesson-019.md","filePath":"life/english/new-concept/book-1/unit-01/lesson-019.md"}'),o={name:"life/english/new-concept/book-1/unit-01/lesson-019.md"};function i(s,e,l,h,d,c){return a(),n("div",null,[...e[0]||(e[0]=[r('<h1 id="第一册-英语初阶-·-lesson-19-tired-and-thirsty" tabindex="-1">第一册：英语初阶 · Lesson 19 Tired and thirsty <a class="header-anchor" href="#第一册-英语初阶-·-lesson-19-tired-and-thirsty" aria-label="Permalink to &quot;第一册：英语初阶 · Lesson 19 Tired and thirsty&quot;">​</a></h1><p><a href="/life/english/new-concept/overview">系列目录</a> · <a href="/life/english/new-concept/book-1/contents">本册目录</a> · <a href="/life/english/new-concept/book-1/unit-01/overview">单元 1</a> · <a href="/life/english/new-concept/book-1/unit-01/lesson-020">配套课 Lesson 20</a></p><h2 id="学习目标与内容导读" tabindex="-1">学习目标与内容导读 <a class="header-anchor" href="#学习目标与内容导读" aria-label="Permalink to &quot;学习目标与内容导读&quot;">​</a></h2><p>描述多人状态并用代词指代 本课要掌握主格和宾格，能够理解人物、对象及说话目的，并把相同结构用于自己的生活。先根据情境判断为什么要这样问或这样说，再看语言形式。</p><p>本课为情景学习；完成后进入相邻偶数课进行句型迁移。</p><h2 id="单词与搭配" tabindex="-1">单词与搭配 <a class="header-anchor" href="#单词与搭配" aria-label="Permalink to &quot;单词与搭配&quot;">​</a></h2><table tabindex="0"><thead><tr><th>单词</th><th>音标</th><th>词性</th><th>本页义项</th><th>搭配</th></tr></thead><tbody><tr><td>tired</td><td>/ˈtaɪəd/</td><td>adj.</td><td>疲倦的</td><td>be tired</td></tr><tr><td>thirsty</td><td>/ˈθɜːsti/</td><td>adj.</td><td>口渴的</td><td>feel thirsty</td></tr><tr><td>hungry</td><td>/ˈhʌŋɡri/</td><td>adj.</td><td>饥饿的</td><td>be hungry</td></tr><tr><td>them</td><td>/ðem/</td><td>pron.</td><td>他们（宾格）</td><td>look at them</td></tr></tbody></table><h2 id="短语与句型" tabindex="-1">短语与句型 <a class="header-anchor" href="#短语与句型" aria-label="Permalink to &quot;短语与句型&quot;">​</a></h2><ul><li>tired and hungry — 并列描述状态</li><li>look at them — 介词后用宾格</li></ul><h2 id="语法讲解-主格和宾格" tabindex="-1">语法讲解：主格和宾格 <a class="header-anchor" href="#语法讲解-主格和宾格" aria-label="Permalink to &quot;语法讲解：主格和宾格&quot;">​</a></h2><p>主语位置用 I/he/she/we/they，动词或介词后的宾语位置用 me/him/her/us/them。Look at 后需要宾格，如 Look at them。形容词描述人的状态时仍需要 be；多个形容词可用 and 连接。先判断代词在句中的角色，再决定形式，不要只按中文“他们”选 they。</p><h2 id="原创例句与结构分析" tabindex="-1">原创例句与结构分析 <a class="header-anchor" href="#原创例句与结构分析" aria-label="Permalink to &quot;原创例句与结构分析&quot;">​</a></h2><blockquote><p>The runners are tired and hungry.</p></blockquote><p>跑步的人又累又饿。</p><p>The runners 是复数主语，are 后接两个由 and 连接的表语 tired 和 hungry；形容词不加复数 s。</p><h2 id="易错辨析" tabindex="-1">易错辨析 <a class="header-anchor" href="#易错辨析" aria-label="Permalink to &quot;易错辨析&quot;">​</a></h2><p>look at they 应改为 look at them；they 在此不是主语。</p><h2 id="听说训练" tabindex="-1">听说训练 <a class="header-anchor" href="#听说训练" aria-label="Permalink to &quot;听说训练&quot;">​</a></h2><p>请同伴朗读本课原创示范，或先自行录音，再遮住文字听写“The runners are tired and hungry.”。核对词序与漏词后，用下方句子分析说明每个词组的作用。随后不看原句说出中文意思，再换一个对象重新说一句。没有录音时，可用同伴朗读和问答完成同样的训练。</p><h2 id="读写训练" tabindex="-1">读写训练 <a class="header-anchor" href="#读写训练" aria-label="Permalink to &quot;读写训练&quot;">​</a></h2><h3 id="阅读材料-本站原创" tabindex="-1">阅读材料（本站原创） <a class="header-anchor" href="#阅读材料-本站原创" aria-label="Permalink to &quot;阅读材料（本站原创）&quot;">​</a></h3><p>The runners are tired and hungry. Look at them near the gate.</p><h3 id="表达任务" tabindex="-1">表达任务 <a class="header-anchor" href="#表达任务" aria-label="Permalink to &quot;表达任务&quot;">​</a></h3><p>围绕“描述多人状态并用代词指代”写两至三句，再读给同伴听。至少使用一次主格和宾格，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>写作提示与点评</summary><p>The runners 是复数主语，are 后接两个由 and 连接的表语 tired 和 hungry；形容词不加复数 s。 Look at 是观察动作，them 是介词 at 的宾语；near the gate 补充被观察者所在的位置。</p></details><h2 id="课后自测" tabindex="-1">课后自测 <a class="header-anchor" href="#课后自测" aria-label="Permalink to &quot;课后自测&quot;">​</a></h2><h3 id="练习-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1" aria-label="Permalink to &quot;练习 1&quot;">​</a></h3><p>填 be：The runners ___ tired.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> are</p><p><strong>解析：</strong> 按本课规则判断：主语位置用 I/he/she/we/they，动词或介词后的宾语位置用 me/him/her/us/them。Look at 后需要宾格，如 Look at them。形容词描述人的状态时仍需要 be；多个形容词可用 and 连接。先判断代词在句中的角色，再决定形式，不要只按中文“他们”选 they。</p></details><h3 id="练习-2" tabindex="-1">练习 2 <a class="header-anchor" href="#练习-2" aria-label="Permalink to &quot;练习 2&quot;">​</a></h3><p>把“跑步的人又累又饿。”译成英语，保留人物、动作与时间信息。</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> The runners are tired and hungry.</p><p><strong>解析：</strong> The runners 是复数主语，are 后接两个由 and 连接的表语 tired 和 hungry；形容词不加复数 s。</p></details><h3 id="练习-3" tabindex="-1">练习 3 <a class="header-anchor" href="#练习-3" aria-label="Permalink to &quot;练习 3&quot;">​</a></h3><p>说明下面句子表达的信息，并译成中文：Look at them near the gate.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> 看门附近的他们。</p><p><strong>解析：</strong> Look at 是观察动作，them 是介词 at 的宾语；near the gate 补充被观察者所在的位置。</p></details><h2 id="复习导航" tabindex="-1">复习导航 <a class="header-anchor" href="#复习导航" aria-label="Permalink to &quot;复习导航&quot;">​</a></h2><p>本课重点：主格和宾格。复习时先遮住答案重做自测，再将示范中的人物、时间或条件改为自己的情境；解释改动后哪些词需要变化。</p><p><a href="/life/english/new-concept/book-1/unit-01/grammar">单元语法</a> · <a href="/life/english/new-concept/book-1/unit-01/vocabulary">单元单词</a> · <a href="/life/english/new-concept/book-1/unit-01/review">单元自测</a></p><p><a href="/life/english/new-concept/book-1/unit-01/lesson-018">上一课</a> · <a href="/life/english/new-concept/book-1/unit-01/overview">单元目录</a> · <a href="/life/english/new-concept/book-1/unit-01/lesson-020">下一课</a></p><hr><p>本站原创学习伴读：保留经典版课号和课名，讲解、例句与练习独立编写。重点词汇用于本页学习，不等同于教材全部生词表；教材课文、完整译文、原题与录音请配合自己的正版教材使用。</p>',41)])])}const b=t(o,[["render",i]]);export{p as __pageData,b as default};
